from datetime import datetime

todo_threads = [
    t for t in (inbox_threads + arch_threads)
    if (t.get('subject') or '').startswith('TODO')
]
# sort by thread id
thread_ids = sorted([t['email_thread_id'] for t in todo_threads])
print('todo_thread_ids', thread_ids)

selected_reply_info = {}
for tid in thread_ids:
    th = apis.gmail.show_thread(email_thread_id=tid, access_token=gmail_access_token)
    emails = th.get('emails', [])
    # pick most recent email not from me
    candidates = [e for e in emails if e.get('sender', {}).get('email') != my_email]
    if not candidates:
        # fallback: pick most recent overall
        candidates = emails
    # choose by created_at timestamp
    def parse_dt(s):
        try:
            return datetime.fromisoformat(s.replace('Z','+00:00'))
        except Exception:
            return datetime.min
    chosen = max(candidates, key=lambda e: parse_dt(e.get('created_at')))
    selected_reply_info[tid] = {
        'chosen_email_id': chosen.get('email_id'),
        'chosen_sender': chosen.get('sender', {}),
        'chosen_created_at': chosen.get('created_at'),
        'thread_created_at': th.get('created_at'),
        'emails_count': len(emails),
        'subject': th.get('subject')
    }
    print('thread', tid, 'subject', th.get('subject'), 'emails_count', len(emails))
    print(' chosen_email_id', chosen.get('email_id'), 'from', chosen.get('sender'), 'created_at', chosen.get('created_at'))

